let verificationState=null;
const verificationPage=document.createElement('section');verificationPage.id='verification';verificationPage.hidden=true;verificationPage.innerHTML=`<span class="eyebrow">WHOLESALER ONBOARDING</span><h1>Tell us about your business.</h1><p class="muted">Complete this demo step before adding or changing stock.</p><div class="verification-notice"><strong>Sample documents only</strong><p>Do not upload Aadhaar, PAN, real identity documents or financial records. Download the dummy templates below and upload them as TXT files. This demonstrates onboarding, not real identity verification.</p><button type="button" id="downloadIdentity" class="orderbtn">Download dummy identity document</button><button type="button" id="downloadBusiness" class="orderbtn">Download dummy business document</button></div><div id="verificationComplete" hidden class="verification-notice"><strong>Demo onboarding complete</strong><p>Your stock tools are unlocked. This does not verify a real business identity.</p><button id="backToStock" class="primary" type="button">Go to my inventory →</button></div><form id="verificationForm"><div class="product-form-grid"><label>Business name<input id="verifyBusiness" maxlength="100" required></label><label>Owner / representative name<input id="verifyOwner" maxlength="60" required></label><label>Business type<select id="verifyType"><option>General wholesale</option><option>Food & groceries</option><option>Packaging & supplies</option></select></label><label>Business address<input id="verifyAddress" maxlength="250" required></label><label>City<input id="verifyCity" maxlength="80" required></label><label>Postal code<input id="verifyPincode" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" required></label><label>Sample contact number<input id="verifyPhone" pattern="[0-9]{10}" maxlength="10" inputmode="numeric" placeholder="9999900001" required></label><label>Dummy identity document<input id="verifyIdentityFile" type="file" accept=".txt,text/plain" required></label><label>Dummy business document<input id="verifyBusinessFile" type="file" accept=".txt,text/plain" required></label></div><label class="promotion-consent"><input id="verifyConsent" type="checkbox" required><span>I am using dummy documents and sample business details only.</span></label><p id="verificationError" class="auth-error" role="alert"></p><button id="verificationSubmit" class="primary">Submit demo documents & unlock stock →</button></form>`;document.querySelector('main').insertBefore(verificationPage,document.querySelector('main footer'));
const verificationNav=document.createElement('button');verificationNav.dataset.page='verification';verificationNav.hidden=true;verificationNav.textContent='✓ Business verification';document.querySelector('nav').append(verificationNav);
const stockGate=document.createElement('div');stockGate.className='verification-notice';stockGate.innerHTML='<strong>Complete your business onboarding</strong><p>Submit dummy documents and business details to unlock stock management.</p><button id="openVerification" type="button" class="primary">Complete verification →</button>';$('#supplier').insertBefore(stockGate,$('#supplier .add-product-panel'));
function applyVerificationGate(){const ready=verificationState?.status==='demo_complete';$('#supplier .add-product-panel').hidden=!ready;$('#inventory').hidden=!ready;stockGate.hidden=ready;$('#verificationComplete').hidden=!ready;$('#verificationForm').hidden=ready}
function showVerification(){['market','orders','supplier','verification'].forEach(id=>$('#'+id).hidden=id!=='verification');document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page==='verification'));window.scrollTo(0,0);translateUI()}
verificationNav.onclick=showVerification;$('#openVerification').onclick=showVerification;$('#backToStock').onclick=()=>document.querySelector('[data-page="supplier"]').click();
document.querySelectorAll('[data-page]').forEach(b=>{if(b===verificationNav)return;const previous=b.onclick;b.onclick=()=>{verificationPage.hidden=true;previous();applyVerificationGate()}});
const originalEnterAccount=enterAccount;enterAccount=async user=>{verificationState=null;applyVerificationGate();verificationNav.hidden=user.role!=='wholesaler';await originalEnterAccount(user);if(user.role!=='wholesaler')return;$('#verifyBusiness').value=user.supplier;$('#verifyOwner').value=user.name;try{const data=await api('/verification');verificationState=data.verification;applyVerificationGate();if(!verificationState)showVerification()}catch(error){$('#verificationError').textContent=error.message;showVerification()}};
function downloadSample(kind){const content='VOCALVEND DEMO DOCUMENT\n\nDocument type: '+kind+'\nSample name: Demo Wholesaler\nReference: DEMO-ONLY-001\n\nFICTIONAL DOCUMENT — NOT VALID FOR IDENTIFICATION\n';const url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));const link=document.createElement('a');link.href=url;link.download='vocalvend-dummy-'+kind+'.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#downloadIdentity').onclick=()=>downloadSample('identity');$('#downloadBusiness').onclick=()=>downloadSample('business');
async function readDummyFile(input){const file=input.files[0];if(!file||!file.name.toLowerCase().endsWith('.txt')||file.size>20000)throw new Error('Upload both sample TXT documents using the provided templates.');return {name:file.name,content:await file.text()}}
$('#verificationForm').onsubmit=async e=>{e.preventDefault();const button=$('#verificationSubmit');button.disabled=true;$('#verificationError').textContent='';try{const data={businessName:$('#verifyBusiness').value,ownerName:$('#verifyOwner').value,businessType:$('#verifyType').value,address:$('#verifyAddress').value,city:$('#verifyCity').value,pincode:$('#verifyPincode').value,phone:$('#verifyPhone').value,dummyConfirmed:$('#verifyConsent').checked,identityDocument:await readDummyFile($('#verifyIdentityFile')),businessDocument:await readDummyFile($('#verifyBusinessFile'))};validateVerification(data);await api('/verification',{method:'POST',body:JSON.stringify(data)});verificationState=(await api('/verification')).verification;applyVerificationGate();$('#verificationForm').reset();await refreshMarket();toast('Demo onboarding complete. Stock management is unlocked.')}catch(error){$('#verificationError').textContent=error.message;translateUI()}finally{button.disabled=false}};applyVerificationGate();translateUI();
